/**
 * Centralized email templates. Every transactional email the app sends
 * is generated by a function here, so branding/copy stays consistent and
 * controllers stay focused on business logic instead of HTML strings.
 * Each function returns { subject, html } ready to pass to sendEmail().
 */

const contactAdminNotification = ({ name, email, company, phone, budgetRange, projectType, subject, message }) => ({
  subject: `New contact inquiry: ${subject}`,
  html: `
    <p><strong>${name}</strong> (${email}) sent a new inquiry.</p>
    <p><strong>Company:</strong> ${company || 'N/A'}</p>
    <p><strong>Phone:</strong> ${phone || 'N/A'}</p>
    <p><strong>Budget:</strong> ${budgetRange || 'Not specified'}</p>
    <p><strong>Project type:</strong> ${projectType || 'N/A'}</p>
    <p><strong>Message:</strong><br/>${message.replace(/\n/g, '<br/>')}</p>
  `,
});

const contactAutoReply = ({ name, subject }) => ({
  subject: "We've received your message — Abacus Digital Agency",
  html: `
    <p>Hi ${name},</p>
    <p>Thanks for reaching out to Abacus Digital Agency. We've received your message about
    "<strong>${subject}</strong>" and a member of our team will get back to you within one
    business day.</p>
    <p>— The Abacus Digital Agency Team</p>
  `,
});

const contactReply = ({ name, subject, message }) => ({
  subject: `Re: ${subject}`,
  html: `<p>Hi ${name},</p><p>${message.replace(/\n/g, '<br/>')}</p><p>— The Abacus Digital Agency Team</p>`,
});

const newsletterWelcome = () => ({
  subject: 'Welcome to the Abacus Digital Agency newsletter',
  html: `
    <p>Thanks for subscribing! You'll now get occasional updates on our latest projects,
    engineering write-ups, and open roles — no spam, unsubscribe any time.</p>
  `,
});

const applicationAdminNotification = ({ name, email, jobTitle, resumeUrl }) => ({
  subject: `New application: ${jobTitle}`,
  html: `<p><strong>${name}</strong> (${email}) applied for <strong>${jobTitle}</strong>.</p>
    <p>Resume: <a href="${resumeUrl}">${resumeUrl}</a></p>`,
});

const applicationConfirmation = ({ name, jobTitle }) => ({
  subject: `Application received — ${jobTitle} at Abacus Digital Agency`,
  html: `<p>Hi ${name},</p><p>We've received your application for
    <strong>${jobTitle}</strong>. Our talent team will review it and reach out if
    there's a fit.</p><p>— The Abacus Digital Agency Team</p>`,
});

const APPLICATION_STATUS_COPY = {
  shortlisted: "Good news — you've been shortlisted for the next step in our process.",
  rejected: "We've decided to move forward with other candidates for this role at this time.",
  hired: "Congratulations — we'd like to move forward with an offer!",
};

const applicationStatusUpdate = ({ name, status }) => ({
  subject: 'Update on your application — Abacus Digital Agency',
  html: `<p>Hi ${name},</p><p>${APPLICATION_STATUS_COPY[status] || 'Your application status has been updated.'}</p><p>— The Abacus Digital Agency Team</p>`,
});

module.exports = {
  contactAdminNotification,
  contactAutoReply,
  contactReply,
  newsletterWelcome,
  applicationAdminNotification,
  applicationConfirmation,
  applicationStatusUpdate,
};
